def main():
    for locale, values in COPY.items():
        values = values + [MEMORY_INSTRUCTION[locale]]
        assert len(values) == len(KEYS), locale
        path = ROOT / f"{locale}.lproj/Localizable.strings"
        text = path.read_text()
        for key, value in zip(KEYS, values):
            entry = json.dumps(key, ensure_ascii=False) + " = " + json.dumps(value, ensure_ascii=False) + ";"
            pattern = r'^"' + re.escape(key) + r'"\s*=.*;$'
            if re.search(pattern, text, re.M):
                text = re.sub(pattern, lambda _: entry, text, flags=re.M)
            else:
                text += "\n" + entry
        # Keep the application name correct in the existing planner subtitle.
        text = re.sub(r'(^"tasks\.plan\.subtitle"[^\n]*)', lambda m: m[0].replace("Dots Harness", "HerNess"), text, flags=re.M)
        path.write_text(text.rstrip() + "\n")
    print(f"Updated {len(KEYS)} task suggestion strings in {len(COPY)} languages.")

if __name__ == "__main__":
    main()
